(function(){
 const $=id=>document.getElementById(id);let limit=30,selected=null;
 const normal=v=>String(v||'').normalize('NFKC').toLowerCase().replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-96));
 window.renderCharacterFragments=()=>{const balance=$('fragment-balance');if(!balance)return;balance.textContent=KanjiFragments.balance(gameState).toLocaleString();const summary=$('fragment-summary-balance');if(summary)summary.textContent=balance.textContent;if(!$('fragment-exchange-panel').open)return;const query=$('fragment-search').value,jis=$('fragment-filter-jis').value,attr=$('fragment-filter-attr').value,sort=$('fragment-filter-sort').value||'jis_asc',candidates=KANJI_DATABASE.filter(i=>KanjiFragments.eligible(gameState,i,getRealReadings)).map(i=>{const ruby=getRealReadings(i.char)[0];return {...i,level:1,ruby,unlockedReadings:[ruby],equippedReadings:[ruby]};}),list=KanjiPracticePicker.filter(candidates,{query,jis,attr,sort},getRealReadings,i=>KanjiReadAbilities.resolveAll(i),getKanjiStats,i=>i.unlockedReadings.length,KanjiTurnOrder.count);if(sort==='jis_asc')list.sort((a,b)=>KanjiPracticePicker.compareJis(a,b,false)||a.char.localeCompare(b.char,'ja'));const box=$('fragment-choices');box.replaceChildren();for(const base of list.slice(0,limit)){const b=document.createElement('button'),glyph=document.createElement('strong'),note=document.createElement('span');b.type='button';b.className='practice-owned-choice';glyph.className='kanji-font';glyph.textContent=base.char;note.textContent=`${getCharacterTypeLabel(base)}・${KanjiFragments.costs[base.jis]}個`;b.append(glyph,note);b.setAttribute('aria-pressed',String(selected===base.id));b.onclick=()=>{selected=base.id;renderCharacterFragments();};box.append(b);}if(!list.length){const p=document.createElement('p');p.textContent='交換できる文字がありません。発見済みの通常文字が対象です。';box.append(p);}$('fragment-count').textContent=`対象 ${list.length}種類・${Math.min(limit,list.length)}種類を表示`;$('btn-fragment-more').hidden=list.length<=limit;const base=KANJI_DATABASE.find(i=>i.id===selected),cost=base?KanjiFragments.costs[base.jis]:0;$('fragment-selection').textContent=base?`「${base.char}」Lv.1 ×1体 ／ かけら ${cost}個 → 残り ${Math.max(0,KanjiFragments.balance(gameState)-cost)}個`:'交換したい文字を選んでください。';const button=$('btn-fragment-exchange');button.disabled=!base||!KanjiFragments.eligible(gameState,base,getRealReadings)||KanjiFragments.balance(gameState)<cost||saveRecoveryBlocked||!saveStore||saveStore.blocked;button.textContent=base&&KanjiFragments.balance(gameState)<cost?`かけらが${cost-KanjiFragments.balance(gameState)}個不足`:'選んだ文字と交換';};
 window.exchangeCharacterFragments=()=>{if($('btn-fragment-exchange').disabled)return;let committed=false;try{const outcome=KanjiFragments.exchange(gameState,selected,KANJI_DATABASE,getRealReadings,base=>{const item={...base,instanceId:newInstanceId(),level:1,exp:0,ruby:'',locked:false};autoEquipReading(item);return KanjiInventory.normalize(item,getRealReadings);});const next=outcome.state;next.characterDiscoveries=[...(next.characterDiscoveries||[])];next.specialDiscoveries=[...(next.specialDiscoveries||[])];KanjiCollection.register(next,outcome.item,getRealReadings);if(saveRecoveryBlocked||!saveStore||saveStore.blocked)throw Error('save-protected');saveStore.write(next);gameState=next;committed=true;saveState(true);renderCollection();renderDeckSlots();renderSynthesisGrid();renderCharacterFragments();$('fragment-status').textContent=`「${outcome.item.char}」を1体入手しました。かけら${outcome.cost}個を使用。`;showGachaResults([{item:outcome.item,duplicate:outcome.duplicate,fragmentExchange:true,firstDiscovery:false}],'exchange');}catch(error){$('fragment-status').textContent=committed?'交換は保存されました。入手画面を開けませんでしたが、所持一覧で確認できます。':error.message==='fragment-shortage'?'かけらが不足しています。':'交換できませんでした。保存データは変更していません。ページを再読み込みして確認してください。';renderCharacterFragments();}};
 window.addEventListener('load',()=>{const panel=$('fragment-exchange-panel');panel.addEventListener('toggle',()=>{if(panel.open)renderCharacterFragments();});for(const id of ['fragment-search','fragment-filter-jis','fragment-filter-attr','fragment-filter-sort'])$(id).addEventListener(id==='fragment-search'?'input':'change',()=>{limit=30;renderCharacterFragments();});$('btn-fragment-more').onclick=()=>{limit+=30;renderCharacterFragments();};renderCharacterFragments();});
})();
